//!extensions/openai/failover-code.ts
function classifyOpenAiFailoverCode(e){switch(e?.trim().toUpperCase()){case`SERVER_ERROR`:return`server_error`;case`INSUFFICIENT_QUOTA`:case`USAGE_NOT_INCLUDED`:case`CREDIT_BALANCE_EXHAUSTED`:case`ORGANIZATION_SPEND_LIMIT_EXCEEDED`:case`ORGANIZATION_USAGE_LIMIT_EXCEEDED`:case`PROJECT_SPEND_LIMIT_EXCEEDED`:return`billing`;case`USAGE_LIMIT_REACHED`:return`rate_limit`;case`CONTEXT_LENGTH_EXCEEDED`:return`context_overflow`;case`INVALID_PROMPT`:case`INVALID_REQUEST_ERROR`:case`CONTENT_POLICY_VIOLATION`:case`CONTENT_FILTER`:return`format`;default:return}}export{classifyOpenAiFailoverCode as t};